def gen(rng):
    B = 10**18
    def fmt(xs):
        return str(len(xs)) + '\n' + ' '.join(map(str, xs))
    tests = [fmt([0]), fmt([B]), fmt([-B]), fmt([7, 7, 7]), fmt([-1, -1, -1, 0]),
             fmt([B] * 10), fmt([-B] * 10), fmt([B, -B, B, -B, B]), fmt([1, 2]), fmt([-1, -2])]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            tests.append(fmt([rng.randint(-20, 20) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([rng.randint(-B, B) for _ in range(15)]))
    tests.append(fmt([rng.randint(-B, B) for _ in range(2000)]))
    tests.append(fmt([rng.choice([B, B - 1, -B, -B + 1]) for _ in range(3000)]))
    tests.append(fmt([rng.randint(-B, B) for _ in range(100000)]))
    tests.append(fmt([B - rng.randint(0, 3) for _ in range(100000)]))
    tests.append(fmt([(-B if i % 2 else B) + rng.randint(-1, 1) * (i % 3 == 0) for i in range(60000)]))
    return tests
